$G1='tv';$I=[Security.Principal.WindowsIdentity]::GetCurrent();$o=[ordered]@{me=$I.User.Value;meName=$I.Name;mePid=$PID;on=$null;child=$null;owner=$null;exited=$null;starts=@();errs=@();cleanup=$null};$ch=$null;try{try{Register-CimIndicationEvent -Query "SELECT * FROM Win32_ProcessStartTrace WHERE ProcessName='powershell.exe'" -SourceIdentifier G1V;$o.on=$true}catch{$o.on=[string]$_.FullyQualifiedErrorId};Start-Sleep -Milliseconds 500;$ch=Start-Process powershell.exe -ArgumentList '-NoProfile','-Command','Start-Sleep -Seconds 2' -WindowStyle Hidden -PassThru;$cp=Get-CimInstance Win32_Process -Filter "ProcessId=$($ch.Id)" -OperationTimeoutSec 5;$o.child=[ordered]@{pid=$ch.Id;ppid=[int]$cp.ParentProcessId;session=[int]$cp.SessionId;created=$cp.CreationDate.ToUniversalTime().ToString('o')};try{$w=Invoke-CimMethod -InputObject $cp -MethodName GetOwner -OperationTimeoutSec 5;$o.owner=[ordered]@{rc=[int]$w.ReturnValue;name=[string]$w.Domain+'\'+[string]$w.User;alive=-not $ch.HasExited}}catch{$o.errs+='owner:'+$_.FullyQualifiedErrorId};$o.exited=$ch.WaitForExit(8000);Start-Sleep -Seconds 2;foreach($e in @(Get-Event -SourceIdentifier G1V -ErrorAction SilentlyContinue)){$n=$e.SourceEventArgs.NewEvent;if([int]$n.ParentProcessID -ne $PID){continue};try{$o.starts+=[ordered]@{pid=[int]$n.ProcessID;ppid=[int]$n.ParentProcessID;session=[int]$n.SessionID;created=[DateTime]::FromFileTimeUtc([int64]$n.TIME_CREATED).ToString('o');sid=(New-Object Security.Principal.SecurityIdentifier([byte[]]$n.Sid,0)).Value}}catch{$o.errs+='event:'+$_.FullyQualifiedErrorId}}}catch{$o.errs+='main:'+$_.FullyQualifiedErrorId}finally{$cl=[ordered]@{};try{Unregister-Event -SourceIdentifier G1V -ErrorAction Stop;$cl.unregistered=$true}catch{$cl.unregistered=[string]$_.FullyQualifiedErrorId};try{Get-Event -SourceIdentifier G1V -ErrorAction SilentlyContinue|Remove-Event}catch{};$cl.subscribers=@(Get-EventSubscriber -SourceIdentifier G1V -ErrorAction SilentlyContinue).Count;if($ch -and -not $ch.HasExited){try{$ch.Kill();$cl.childKilled=$true}catch{$cl.childKilled=[string]$_.FullyQualifiedErrorId}}else{$cl.childKilled=$false};$o.cleanup=$cl}